#!/bin/bash
# land-timestamp-is-not-a-face.sh — the beauty assessment shows only with
# evidence: an analysis event AND the photos it analysed, both.
#
# BACKEND ONLY (together-city-chat). Push, and Railway rebuilds — no
# migration, no schema change. Stale pre-fix rows stay in the DB untouched;
# they simply stop being displayed or refreshed.
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-chat ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
MARK="The lint ceiling reaches the floor"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\" — run land-lint-zero.sh first."; exit 1 ;;
esac
NEEDS="A timestamp is not a face"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

PATCH="$(mktemp "${TMPDIR:-/tmp}/tface.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="4aa1c24917eb013e4d7671146764f81d9b56862fffb06e13cc466769785c9431"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified"
git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
git am --keep-cr -C1 < "$PATCH"
echo "== committed"

cd together-city-chat
npx tsc --noEmit
npx jest src/beauty
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS"
echo " Backend only — push and Railway rebuilds. After deploy, your"
echo " /beauty/profile shows the blank invite state until photos are"
echo " actually uploaded and analysed."
echo "==============================================================="
